//! Hosts store: reads and writes the list of SSH hosts as `hosts.toml` in the
//! OS config directory. This module is intentionally thin — it only does
//! serialization and file I/O; no SSH or product logic lives here.

use std::fs;
use std::fs::File;
use std::io::Write;
use std::path::PathBuf;

use serde::{Deserialize, Serialize};
use tauri::{AppHandle, Manager};

/// A single SSH host entry. `id` is generated by the backend on `add_host` so
/// the frontend has a stable key for update/delete; everything else is
/// user-supplied.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct Host {
    #[serde(default)]
    pub id: String,
    pub name: String,
    pub hostname: String,
    #[serde(default = "default_port")]
    pub port: u16,
    #[serde(default)]
    pub user: String,
    /// Path to a private key on disk. We store the path only — never the key
    /// contents (see CLAUDE.md rules).
    #[serde(default)]
    pub identity_file: Option<String>,
    #[serde(default)]
    pub tags: Vec<String>,
    #[serde(default)]
    pub notes: String,
}

fn default_port() -> u16 {
    22
}

/// On-disk shape of `hosts.toml`: a single `[[hosts]]` array of tables.
#[derive(Debug, Default, Serialize, Deserialize)]
struct HostsFile {
    #[serde(default)]
    hosts: Vec<Host>,
}

/// Resolve `<app config dir>/hosts.toml`, creating the directory if needed.
/// Resolving the path in Rust (rather than via a JS plugin call) means no
/// extra capability grant is required.
fn hosts_path(app: &AppHandle) -> Result<PathBuf, String> {
    let dir = app
        .path()
        .app_config_dir()
        .map_err(|e| format!("could not resolve config dir: {e}"))?;
    fs::create_dir_all(&dir).map_err(|e| format!("could not create config dir: {e}"))?;
    Ok(dir.join("hosts.toml"))
}

/// Load all hosts. A missing file is treated as an empty list (first run).
fn load(app: &AppHandle) -> Result<Vec<Host>, String> {
    let path = hosts_path(app)?;
    if !path.exists() {
        return Ok(Vec::new());
    }
    let text = fs::read_to_string(&path).map_err(|e| format!("could not read {path:?}: {e}"))?;
    let parsed: HostsFile =
        toml::from_str(&text).map_err(|e| format!("could not parse hosts.toml: {e}"))?;
    Ok(parsed.hosts)
}

/// Persist the full list atomically: write to a temp file in the same
/// directory, flush it to disk, back up the previous version, then rename the
/// temp over the target. A crash can therefore never leave a half-written
/// hosts.toml — either the old file or the complete new one is in place.
fn save(app: &AppHandle, hosts: &[Host]) -> Result<(), String> {
    let path = hosts_path(app)?;
    let file = HostsFile {
        hosts: hosts.to_vec(),
    };
    let text = toml::to_string_pretty(&file).map_err(|e| format!("could not serialize: {e}"))?;

    // Write the new content to a sibling temp file. Keeping it in the same
    // directory guarantees the later rename stays on one filesystem, which is
    // what makes that rename atomic.
    let tmp = path.with_extension("toml.tmp");
    {
        let mut f = File::create(&tmp).map_err(|e| format!("could not create {tmp:?}: {e}"))?;
        f.write_all(text.as_bytes())
            .map_err(|e| format!("could not write {tmp:?}: {e}"))?;
        // Flush OS buffers to disk before the rename so the renamed file is
        // guaranteed to hold the full contents.
        f.sync_all()
            .map_err(|e| format!("could not flush {tmp:?}: {e}"))?;
    }

    // Preserve the previous version as hosts.toml.bak before replacing it.
    if path.exists() {
        let bak = path.with_extension("toml.bak");
        fs::copy(&path, &bak).map_err(|e| format!("could not back up to {bak:?}: {e}"))?;
    }

    // Atomic replace: on both Windows and Unix this swaps the target in place.
    fs::rename(&tmp, &path).map_err(|e| format!("could not replace {path:?}: {e}"))
}

#[tauri::command]
pub fn list_hosts(app: AppHandle) -> Result<Vec<Host>, String> {
    load(&app)
}

#[tauri::command]
pub fn add_host(app: AppHandle, mut host: Host) -> Result<Host, String> {
    let mut hosts = load(&app)?;
    // Always mint a fresh id server-side; ignore whatever the frontend sent.
    host.id = uuid::Uuid::new_v4().to_string();
    hosts.push(host.clone());
    save(&app, &hosts)?;
    Ok(host)
}

#[tauri::command]
pub fn update_host(app: AppHandle, host: Host) -> Result<Host, String> {
    let mut hosts = load(&app)?;
    let idx = hosts
        .iter()
        .position(|h| h.id == host.id)
        .ok_or_else(|| format!("host {} not found", host.id))?;
    hosts[idx] = host.clone();
    save(&app, &hosts)?;
    Ok(host)
}

#[tauri::command]
pub fn delete_host(app: AppHandle, id: String) -> Result<(), String> {
    let mut hosts = load(&app)?;
    let before = hosts.len();
    hosts.retain(|h| h.id != id);
    if hosts.len() == before {
        return Err(format!("host {id} not found"));
    }
    save(&app, &hosts)
}
